package org.algoclerk.game;

import android.os.Bundle;
import android.view.View;
import androidx.core.view.WindowCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.core.view.WindowInsetsControllerCompat;
import com.google.androidgamesdk.GameActivity;

/**
 * Hosts the Rust game (libalgoclerk_app.so, entry point `android_main` generated by Bevy's
 * `#[bevy_main]`). The activity only loads the library and keeps the game fullscreen. The activity
 * pattern follows the sibling project Falabichos (Apache-2.0, same owner).
 */
public class MainActivity extends GameActivity {
    static {
        System.loadLibrary("algoclerk_app");
    }

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        WindowCompat.setDecorFitsSystemWindows(getWindow(), false);
        super.onCreate(savedInstanceState);
    }

    @Override
    public void onWindowFocusChanged(boolean hasFocus) {
        super.onWindowFocusChanged(hasFocus);
        if (hasFocus) {
            View decor = getWindow().getDecorView();
            WindowInsetsControllerCompat controller = WindowCompat.getInsetsController(getWindow(), decor);
            controller.setSystemBarsBehavior(WindowInsetsControllerCompat.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);
            controller.hide(WindowInsetsCompat.Type.systemBars());
        }
    }
}
